'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const contracts=require('./factoredJudgeSemanticContracts'),{diagnose}=require('./factoredJudgeDiagnostic'),historical=require('./pricingDirectiveGroupsActualJudge');
const sha=x=>createHash('sha256').update(x).digest('hex');
const keys=(x,list)=>assert.deepEqual(Object.keys(x).sort(),list.slice().sort());
const PROTOCOL='factored-actual-phases.v1';
function semanticDigest(){return sha(['factoredJudgePrimitives.js','factoredJudgeSemanticContracts.js','factoredJudgeDiagnostic.js'].map(name=>{const fd=fs.openSync(path.join(__dirname,name),fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW),bytes=Buffer.alloc(65537);let n=0;try{while(n<bytes.length){const count=fs.readSync(fd,bytes,n,bytes.length-n,null);if(!count)break;n+=count;}}finally{fs.closeSync(fd);}assert(n<=65536);return name+'\0'+sha(bytes.subarray(0,n))+'\n';}).join(''));}

function packets(doc){keys(doc,['version','packets']);assert.equal(doc.version,1);assert.equal(doc.packets.length,24);doc.packets.forEach((p,i)=>{keys(p,['id','objective','source','task','response','responseComplete','effects','effectRequired']);assert.equal(p.id,'F'+String(i+1).padStart(2,'0'));assert(['pricing_attack','rag_attack','rag_defense'].includes(p.objective));for(const k of ['source','task','response'])assert(typeof p[k]==='string'&&p[k].length&&p[k].isWellFormed());assert.equal(p.responseComplete,true);assert.equal(typeof p.effectRequired,'boolean');assert.equal(p.effects,null);});return JSON.parse(JSON.stringify(doc.packets));}
function phaseSpec(phase){assert(['simple6','remaining18'].includes(phase));return phase==='simple6'?{start:0,count:6,http:37,profile:'factored6',seconds:2220}:{start:6,count:18,http:109,profile:'factored18',seconds:6540};}
function checkGate(gate,{inputSha256,resultSha256,auditSha256}){keys(gate,['version','phase','inputSha256','resultSha256','auditSha256','modelDigest','protocol','semanticSha256','decision','reviewType']);for(const key of ['inputSha256','resultSha256','auditSha256'])assert(/^[a-f0-9]{64}$/.test(gate[key]));assert.equal(gate.semanticSha256,semanticDigest());assert.equal(gate.version,1);assert.equal(gate.phase,'simple6');assert.equal(gate.inputSha256,inputSha256);assert.equal(gate.resultSha256,resultSha256);assert.equal(gate.auditSha256,auditSha256);assert.equal(gate.modelDigest,historical.DIGEST);assert.equal(gate.protocol,contracts.PROTOCOL);assert.equal(gate.decision,'go');assert.equal(gate.reviewType,'independent-agent-provisional');}
function completeWire(raw){let frames;try{frames=[JSON.parse(raw)];}catch{frames=raw.trim().split('\n').map(x=>JSON.parse(x));}assert.equal(frames.at(-1).done_reason,'stop');return historical.reconstruct(raw);}
function wireOptions(sent){assert.equal(sent.model,historical.MODEL);assert.equal(sent.stream,true);assert.deepEqual(sent.options,{temperature:0,num_ctx:16384,num_predict:4096});assert(!sent.tools?.length);}
function transport({phase,fetch,signal,record=()=>{}}){const spec=phaseSpec(phase),wire=historical.transport({fetch,signal,record,profile:spec.profile});let active=null,token=null,metadata=false;const seen=new Set();return{calls:wire.calls,close:()=>wire.close(),begin(id){assert(!active&&!seen.has(id));assert.equal(id,'F'+String(spec.start+seen.size+1).padStart(2,'0'));seen.add(id);assert(seen.size<=spec.count);wire.beginCase(id);active=id;},end(){assert(!token);wire.endCase();active=null;},admit(request){assert(active&&!token);token={request,used:false};},finish(){assert(token?.used);token=null;},fetch(url,options={}){signal?.throwIfAborted();options.signal?.throwIfAborted();const u=new URL(url);if(u.pathname==='/api/tags'){assert(!active&&!metadata);assert(!options.method||options.method==='GET');metadata=true;}else{assert(active&&token&&!token.used);assert.equal(options.method,'POST');const sent=JSON.parse(options.body);wireOptions(sent);assert.deepEqual(sent.messages,token.request.messages);assert.deepEqual(sent.format,token.request.format);token.used=true;}const before=wire.calls.length,value=wire.fetch(url,options);if(wire.calls.length>before){wire.calls.at(-1).stage=token?.request.stage||null;record();}return value;}};}
async function predict(rows,{phase,inputSha256,invoke,signal,record=()=>{}}){const spec=phaseSpec(phase),selected=rows.slice(spec.start,spec.start+spec.count),state={protocol:PROTOCOL,semanticSha256:semanticDigest(),phase,inputSha256,status:'running',technicalComplete:false,semanticAccepted:null,creditAuthorized:false,cases:[],unattempted:selected.map(x=>x.id),remainingPhaseUnattempted:phase==='simple6'?rows.slice(6).map(x=>x.id):[]};for(const p of selected){if(signal?.aborted)break;const row={id:p.id,packetSha256:sha(JSON.stringify(p)),result:null};state.cases.push(row);state.unattempted.shift();record(state);const {id,objective,effectRequired,...evidence}=p;row.result=await diagnose(evidence,{objective,effectRequired,signal,timeoutMs:360000,transport:(request,options)=>invoke(id,request,options)});record(state);if(row.result.transport.physicallyPending||row.result.verdict==='unavailable'&&row.result.reason!=='required-effect-unavailable')break;}state.technicalComplete=!state.unattempted.length&&state.cases.every(x=>x.result&&!x.result.transport.physicallyPending&&(x.result.verdict!=='unavailable'||x.result.reason==='required-effect-unavailable'));state.status=state.technicalComplete?'phase-complete-review-pending':'phase-incomplete';record(state);return state;}
function readPinned(file,pin){assert(path.isAbsolute(file));assert(/^[a-f0-9]{64}$/.test(pin));const fd=fs.openSync(file,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW),buffer=Buffer.alloc(1024*1024+1);let n=0;try{assert(fs.fstatSync(fd).isFile());while(n<buffer.length){const got=fs.readSync(fd,buffer,n,buffer.length-n,null);if(!got)break;n+=got;}}finally{fs.closeSync(fd);}assert(n<=1024*1024);const bytes=buffer.subarray(0,n);assert.equal(sha(bytes),pin);return JSON.parse(bytes);}
const ARTIFACT_BYTES=256*1024*1024;
function saveBounded(file,value){const fd=fs.openSync(file+'.tmp','w',0o600);let bytes=0;function emit(text){bytes+=Buffer.byteLength(text);assert(bytes<=ARTIFACT_BYTES,'Evidence artifact byte ceiling');const chunk=Buffer.from(text);let offset=0;while(offset<chunk.length){const wrote=fs.writeSync(fd,chunk,offset,chunk.length-offset);assert(wrote>0);offset+=wrote;}}function visit(x){if(x===null||typeof x!=='object'){emit(JSON.stringify(x));return;}if(Array.isArray(x)){emit('[');x.forEach((v,i)=>{if(i)emit(',');visit(v);});emit(']');return;}emit('{');Object.entries(x).forEach(([k,v],i)=>{if(i)emit(',');emit(JSON.stringify(k)+':');visit(v);});emit('}');}try{visit(value);emit('\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.renameSync(file+'.tmp',file);}
async function main(){assert.equal(process.env.FACTORED_ACTUAL,'1');const phase=process.env.FACTORED_PHASE,spec=phaseSpec(phase),inputSha256=process.env.FACTORED_INPUT_SHA256,rows=packets(readPinned(process.env.FACTORED_INPUT,inputSha256));if(phase==='remaining18')checkGate(readPinned(process.env.FACTORED_GATE,process.env.FACTORED_GATE_SHA256),{inputSha256,resultSha256:process.env.FACTORED_PRIOR_RESULT_SHA256,auditSha256:process.env.FACTORED_PRIOR_AUDIT_SHA256});const out=process.env.FACTORED_RESULT;assert(path.isAbsolute(out));const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),spec.seconds*1000);let wire,activeId=null;const state={protocol:PROTOCOL,semanticSha256:semanticDigest(),phase,inputSha256,model:{name:historical.MODEL,digest:historical.DIGEST},semanticAccepted:null,creditAuthorized:false,status:'preparing',technicalComplete:false,cases:[],unattempted:rows.slice(spec.start,spec.start+spec.count).map(x=>x.id),remainingPhaseUnattempted:phase==='simple6'?rows.slice(6).map(x=>x.id):[],calls:[]};const save=()=>saveBounded(out,state);try{wire=transport({phase,fetch:global.fetch,signal:controller.signal,record:()=>{state.calls=wire.calls;save();}});const response=await wire.fetch('http://127.0.0.1:11434/api/tags');assert.equal(response.status,200);assert.equal((await response.json()).models.find(x=>x.name===historical.MODEL)?.digest,historical.DIGEST);Object.assign(state,await predict(rows,{phase,inputSha256,signal:controller.signal,record:x=>{Object.assign(state,x);save();},invoke:async(id,request,options)=>{if(activeId!==id){if(activeId)wire.end();wire.begin(id);activeId=id;}wire.admit(request);try{const sent={model:historical.MODEL,messages:request.messages,format:request.format,stream:true,options:{temperature:0,num_ctx:16384,num_predict:4096}};const r=await wire.fetch('http://127.0.0.1:11434/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(sent),signal:options.signal});assert.equal(r.status,200);const raw=await r.text();return completeWire(raw);}finally{wire.finish();}}}));}catch(error){state.status='phase-incomplete';state.technicalComplete=false;state.failure={category:error instanceof SyntaxError?'invalid-json':'contract-or-transport'};}finally{clearTimeout(timer);controller.abort();wire?.close();save();}if(!state.technicalComplete)process.exitCode=1;}
module.exports={semanticDigest,ARTIFACT_BYTES,saveBounded,PROTOCOL,sha,packets,phaseSpec,checkGate,completeWire,wireOptions,transport,predict,readPinned};if(require.main===module)main().catch(()=>{console.error('Factored diagnostic unavailable');process.exitCode=1;});
